import { Router } from 'express';
import { dealController } from './deal.controller.js';
import { authGuard } from '../../shared/middleware/authGuard.middleware.js';
import { tenantContext } from '../../shared/middleware/tenantContext.middleware.js';
import { asyncHandler } from '../../shared/middleware/asyncHandler.middleware.js';
import { validate } from '../../shared/middleware/validate.middeware.js';
import { moveStageSchema, updateDealSchema } from './deal.schema.js';
const router = Router();
router.use(authGuard, tenantContext);
router.get('/deal-list', asyncHandler(dealController.list));
router.get('/deal-stages', asyncHandler(dealController.groupStage));
router.get('/:id', asyncHandler(dealController.getById));
router.patch('/:id', validate({ body: updateDealSchema }), asyncHandler(dealController.updateStage));
router.patch('/:id/move-stage', validate({ body: moveStageSchema }), asyncHandler(dealController.moveStage));
router.delete('/:id', asyncHandler(dealController.deleteDeal));
export default router;
